package medium;public class LongestIncreasingPathInMatrix{int[][]m;int[][]dp;int[][]d={{0,1},{0,-1},{1,0},{-1,0}};public int longestIncreasingPath(int[][]matrix){m=matrix;dp=new int[m.length][m[0].length];int ans=0;for(int i=0;i<m.length;i++)for(int j=0;j<m[0].length;j++)ans=Math.max(ans,dfs(i,j));return ans;}int dfs(int i,int j){if(dp[i][j]!=0)return dp[i][j];int mx=1;for(int[]dir:d){int ni=i+dir[0],nj=j+dir[1];if(ni>=0&&ni<m.length&&nj>=0&&nj<m[0].length&&m[ni][nj]>m[i][j])mx=Math.max(mx,1+dfs(ni,nj));}return dp[i][j]=mx;}public static void main(String[]args){System.out.println("Longest path works\n");}}
